/* ===================== BÀI 17 · CMP và nhảy signed/unsigned ===================== */
/* Bài 17 · CMP và nhảy signed/unsigned (AMTS-EMB-002-M05-L01, X86-017) — sinh bởi tools/author/mpu8086/l17.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P17=[{"label": "Ví dụ: CMP rồi JNE, so phím với 'y'", "code": "; Ví dụ 1: so sánh phím vừa gõ với 'y' rồi rẽ nhánh\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 08H                 ; đọc một phím, không hiện\n        INT     21H                     ; AL = mã ASCII của phím\n        MOV     DL, 'K'                 ; giả sử là \"không\"\n        CMP     AL, 'y'                 ; tính AL - 79h, chỉ giữ lại cờ\n        JNE     in_kq                   ; ZF = 0: khác 'y', giữ 'K'\n        MOV     DL, 'C'                 ; ZF = 1: đúng là 'y'\nin_kq:\n        MOV     AH, 02H                 ; in ký tự trong DL\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "y", "note": "Gõ y (dữ liệu nhập có sẵn). CMP AL, 'y' tính 79h − 79h = 0 nên ZF = 1; JNE không nhảy (4 chu kỳ) và DL thành 'C'. Thử sửa ô nhập thành phím khác: JNE nhảy (16 chu kỳ), màn hình in K. Đoán trước: trước JNE, lệnh này có nhảy không? Đáp án: không."}, {"label": "Ví dụ: F0h và 10h, không dấu và có dấu", "code": "; Ví dụ 2: cùng hai byte F0h và 10h, hai kết quả so sánh\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DB      0F0H                    ; 240 nếu không dấu, -16 nếu có dấu\nb       DB      10H                     ; 16 theo cả hai cách hiểu\nkqKD    DB      '<'                     ; kết quả so sánh không dấu\nkqCD    DB      '<'                     ; kết quả so sánh có dấu\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, a\n        CMP     AL, b                   ; F0h - 10h = E0h: CF=0 ZF=0 SF=1 OF=0\n        JBE     xet_cd                  ; không dấu: 240 > 16, không nhảy\n        MOV     kqKD, '>'               ; MOV không đổi cờ\nxet_cd:\n        JLE     het                     ; có dấu: -16 < 16 (SF <> OF), nhảy\n        MOV     kqCD, '>'\nhet:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Cùng CMP AL, b với AL = F0h, b = 10h. JBE (không dấu) không nhảy vì 240 > 16, nên kqKD = '>'. MOV kqKD, '>' không đổi cờ, nên JLE vẫn đọc cờ của CMP: SF = 1, OF = 0 → SF ≠ OF → nhảy, kqCD giữ '<' (−16 < 16). Xem hai biến trong phần Bộ nhớ. Đoán trước: JLE có nhảy không? Đáp án: có."}, {"label": "Ví dụ: 80h − 1 tràn, JA và JL cùng nhảy", "code": "; Ví dụ 3: 80h - 01h tràn có dấu, OF sửa kết luận của SF\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 80H                 ; 128 không dấu, -128 có dấu\n        CMP     AL, 01H                 ; 7Fh: CF=0 ZF=0 SF=0 OF=1\n        MOV     DL, 'A'                 ; 'A' (above) nếu JA nhảy\n        JA      xet_cd                  ; 128 > 1: nhảy\n        MOV     DL, 'B'\nxet_cd:\n        MOV     BL, 'L'                 ; 'L' (less) nếu JL nhảy\n        JL      in_ra                   ; SF <> OF: -128 < 1, nhảy\n        MOV     BL, 'G'\nin_ra:\n        MOV     AH, 02H\n        INT     21H                     ; in DL\n        MOV     DL, BL\n        INT     21H                     ; in BL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "80h − 01h = 7Fh: CF = 0, ZF = 0 → JA nhảy (128 > 1). Có dấu −128 − 1 = −129 không vừa 8 bit: OF = 1, SF = 0; SF ≠ OF → JL nhảy (−128 < 1). Màn hình in AL. Nếu chỉ nhìn SF = 0 sẽ kết luận sai là “không nhỏ hơn”. Đoán trước: sau CMP, ZF bằng bao nhiêu? Đáp án 0."}, {"label": "Lỗi: dùng JA cho nhiệt độ có dấu", "code": "; Ví dụ 4: nhiệt độ -5 và 3 độ, chọn số lớn hơn (CÓ LỖI)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nt1      DB      -5                      ; FBh\nt2      DB      3\nlon     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, t1\n        CMP     AL, t2                  ; FBh - 03h = F8h: CF=0 SF=1 OF=0\n        JA      ghi                     ; LỖI: JA hiểu FBh là 251 > 3\n        MOV     AL, t2                  ; (sửa: JG, vì -5 < 3)\nghi:\n        MOV     lon, AL                 ; lon = FBh = -5: sai\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: −5 (FBh) và 3 là nhiệt độ, có dấu. JA hiểu FBh là 251 > 3 nên nhảy và ghi lon = FBh (−5). Sửa: thay JA bằng JG (ZF = 0 và SF = OF; ở đây SF = 1, OF = 0 nên JG không nhảy, lon = 3). Đoán trước: JA có nhảy không? Đáp án: có (và đó là lỗi)."}, {"label": "Ví dụ: kiểm chữ số bằng hai lần so sánh", "code": "; Ví dụ 5: phím có phải chữ số '0'..'9'? Hai lần so sánh\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 08H\n        INT     21H                     ; AL = phím\n        MOV     DL, 'K'                 ; mặc định: không phải chữ số\n        CMP     AL, '0'\n        JB      in_kq                   ; AL < 30h (không dấu): bỏ qua\n        CMP     AL, '9'\n        JA      in_kq                   ; AL > 39h: bỏ qua\n        MOV     DL, 'S'                 ; 30h <= AL <= 39h: chữ số\nin_kq:\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "7", "note": "Phím 7 (37h). Hai lần so sánh không dấu: 37h ≥ 30h nên JB không nhảy; 37h ≤ 39h nên JA không nhảy; DL = 'S'. Mã ASCII là số không dấu nên dùng JB/JA, không dùng JL/JG. Đoán trước: JA có nhảy không? Đáp án: không."}, {"label": "Ví dụ: kiểm chữ số bằng một lần so sánh", "code": "; Ví dụ 6: cùng việc với Ví dụ 5, một phép so sánh không dấu\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 08H\n        INT     21H                     ; AL = phím\n        MOV     DL, 'K'\n        SUB     AL, '0'                 ; '0'..'9' thành 0..9\n        CMP     AL, 9                   ; ký tự khác thành số > 9 (không dấu)\n        JA      in_kq\n        MOV     DL, 'S'\nin_kq:\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "/", "note": "Phím / (2Fh). SUB AL, '0' cho 2Fh − 30h = FFh = 255 (không dấu). CMP AL, 9 → 255 > 9 nên JA nhảy, in K. Mọi ký tự ngoài '0'…'9' đều thành số > 9, nên một lần so sánh thay được hai (bớt một CMP và một lệnh nhảy). Đoán trước: sau SUB AL, '0', AL bằng bao nhiêu (hệ 16)? Đáp án FFh."}, {"label": "Lỗi: nhảy có điều kiện xa quá 127 byte", "code": "; Ví dụ 7: nhãn cách quá 127 byte (CÓ LỖI DỊCH)\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 5\n        CMP     AL, 5\n        JE      xa                      ; Jcc của 8086 chỉ có dạng ngắn\n        DB      130 DUP(90H)            ; 130 lệnh NOP thay cho đoạn mã dài\nxa:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi dịch cố ý: 130 byte NOP nằm giữa JE và nhãn xa, vượt +127 byte của độ dời 8 bit. Trình dịch báo dòng 8 và gợi ý cách sửa. Sửa: JNE tiep / JMP xa / tiep: — JMP có dạng gần với độ dời 16 bit."}, {"label": "Bẫy: INC chen giữa CMP và JNE", "code": "; Ví dụ 8: lệnh chen giữa CMP và lệnh nhảy làm đổi cờ\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AL, 5\n        MOV     BL, 5\n        MOV     DL, '#'                 ; mặc định: khác nhau\n        CMP     AL, BL                  ; 5 - 5 = 0: ZF = 1\n        INC     SI                      ; BẪY: đếm lần so sánh, INC đặt lại ZF\n        JNE     in_kq                   ; SI = 1 nên ZF = 0: nhảy, in '#'\n        MOV     DL, '='                 ; (sửa: đặt INC SI trước CMP)\nin_kq:\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: AL = BL = 5 nên CMP đặt ZF = 1, nhưng INC SI (đếm số lần so sánh) chạy sau CMP và đặt ZF theo SI = 1, tức ZF = 0. JNE nhảy, in # dù hai số bằng nhau. Sửa: đặt INC SI trước CMP, hoặc dùng lệnh không đổi cờ. Đoán trước: ngay sau INC SI, ZF bằng bao nhiêu? Đáp án 0."}];
const sim17=makeX86Sim(document.getElementById("x86-l17"),{id:"s17",presets:P17,file:"BAI17.ASM"});
makeX86Ex(document.getElementById("ex-l17"),sim17,[{"t": "So sánh hai chữ số", "d": "Đọc hai phím chữ số 0–9 bằng INT 21h hàm 08h (không hiện). So sánh chữ số thứ nhất với chữ số thứ hai, ghi một ký tự vào biến kq: '<' nếu nhỏ hơn, '=' nếu bằng, '>' nếu lớn hơn; rồi in ký tự đó bằng INT 21h hàm 02h. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: so sánh hai chữ số\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DB      ?                       ; '<', '=' hoặc '>'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; AL = chữ số thứ nhất\n        MOV     BL, AL                  ; cất vào BL\n        MOV     AH, 08H\n        INT     21H                     ; AL = chữ số thứ hai\n; Viết tiếp: so sánh BL với AL, ghi '<', '=' hoặc '>'\n; vào kq rồi in kq bằng INT 21h hàm 02h.\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "37", "out": "<", "mem": [{"at": "kq", "bytes": [60]}]}, {"in": "73", "out": ">", "mem": [{"at": "kq", "bytes": [62]}]}, {"in": "55", "out": "=", "mem": [{"at": "kq", "bytes": [61]}]}, {"in": "09", "out": "<", "mem": [{"at": "kq", "bytes": [60]}]}, {"in": "90", "out": ">", "mem": [{"at": "kq", "bytes": [62]}]}, {"in": "00", "out": "=", "mem": [{"at": "kq", "bytes": [61]}]}]}, {"t": "Số lớn hơn khi có dấu", "d": "Code mẫu đọc hai phím chữ số và trừ '5' để được hai số có dấu a, b trong khoảng −5…4 (byte bù 2, ví dụ −5 = FBh). Viết tiếp để ghi vào biến lon số lớn hơn của a và b, so sánh theo kiểu có dấu. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: số lớn hơn khi hiểu là số có dấu\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DB      ?                       ; chữ số thứ nhất - 5 (từ -5 tới 4)\nb       DB      ?                       ; chữ số thứ hai - 5\nlon     DB      ?                       ; số lớn hơn của a và b (có dấu)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '5'                 ; '0'..'9' thành -5..4\n        MOV     a, AL\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '5'\n        MOV     b, AL\n; Viết tiếp: ghi vào lon số lớn hơn của a và b.\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "09", "mem": [{"at": "a", "bytes": [251]}, {"at": "b", "bytes": [4]}, {"at": "lon", "bytes": [4]}]}, {"in": "90", "mem": [{"at": "a", "bytes": [4]}, {"at": "b", "bytes": [251]}, {"at": "lon", "bytes": [4]}]}, {"in": "34", "mem": [{"at": "a", "bytes": [254]}, {"at": "b", "bytes": [255]}, {"at": "lon", "bytes": [255]}]}, {"in": "55", "mem": [{"at": "a", "bytes": [0]}, {"at": "b", "bytes": [0]}, {"at": "lon", "bytes": [0]}]}, {"in": "02", "mem": [{"at": "a", "bytes": [251]}, {"at": "b", "bytes": [253]}, {"at": "lon", "bytes": [253]}]}, {"in": "81", "mem": [{"at": "a", "bytes": [3]}, {"at": "b", "bytes": [252]}, {"at": "lon", "bytes": [3]}]}]}, {"t": "Đếm chữ số nhanh hơn", "d": "Đọc 6 phím bằng INT 21h hàm 08h và ghi vào biến dem (1 byte) số phím là chữ số '0'–'9'. Code mẫu đã đúng nhưng mỗi phím tốn hai lần so sánh, hai lệnh nhảy và tăng thẳng ô nhớ. Viết lại để đạt cả giới hạn chu kỳ và giới hạn byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: đếm số phím là chữ số trong 6 phím\n; Bản này đúng nhưng chậm: mỗi phím hai lần so sánh,\n; hai lệnh nhảy và cộng thẳng vào ô nhớ. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DB      ?                       ; số phím là chữ số\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     dem, 0\n        MOV     CL, 6                   ; đọc 6 phím\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        CMP     AL, '0'\n        JB      tiep                    ; nhỏ hơn '0': không đếm\n        CMP     AL, '9'\n        JA      tiep                    ; lớn hơn '9': không đếm\n        INC     dem                     ; tăng ô nhớ: 15 + 6 chu kỳ\ntiep:\n        DEC     CL\n        JNZ     doc\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "123456", "mem": [{"at": "dem", "bytes": [6]}]}, {"in": "abcdef", "mem": [{"at": "dem", "bytes": [0]}]}, {"in": "/09:a ", "mem": [{"at": "dem", "bytes": [2]}]}, {"in": "a1b2c3", "mem": [{"at": "dem", "bytes": [3]}]}, {"in": "      ", "mem": [{"at": "dem", "bytes": [0]}]}, {"in": "9x0y5z", "mem": [{"at": "dem", "bytes": [3]}]}], "perf": {"cycles": 620, "bytes": 36}}]);

makeQuiz("quiz17","score17",[{"q": "AL = 90h, BL = 20h. Sau <code>CMP AL, BL<\/code>, lệnh nào <b>không<\/b> nhảy?", "o": ["<code>JA<\/code>", "<code>JL<\/code>", "<code>JNE<\/code>", "<code>JG<\/code>"], "a": 3, "e": "90h − 20h = 70h: CF = 0, ZF = 0, SF = 0, OF = 1 (−112 − 32 = −144 tràn). Không dấu 144 > 32 nên JA nhảy; có dấu −112 < 32 nên JL nhảy (SF ≠ OF), JG không nhảy; hai số khác nhau nên JNE nhảy."}, {"q": "Biến <code>dodai<\/code> là độ dài chuỗi (0…255). Cần nhảy tới <code>qua_dai<\/code> khi dodai &gt; 80. Viết thế nào?", "o": ["<code>CMP dodai, 80<\/code> / <code>JG qua_dai<\/code>", "<code>CMP dodai, 80<\/code> / <code>JA qua_dai<\/code>", "<code>CMP 80, dodai<\/code> / <code>JA qua_dai<\/code>", "<code>CMP dodai, 80<\/code> / <code>JB qua_dai<\/code>"], "a": 1, "e": "Độ dài là số không dấu nên dùng JA (above). JG sai với dodai ≥ 128 (hiểu là số âm). CMP không nhận số tức thời làm đích. JB nhảy khi nhỏ hơn."}, {"q": "Đoạn sau in gì? <code>MOV AL, 7Fh<\/code> / <code>CMP AL, 80h<\/code> / <code>MOV DL, 'X'<\/code> / <code>JL bo<\/code> / <code>MOV DL, 'Y'<\/code> / <code>bo:<\/code> rồi in DL.", "o": ["X", "Không in gì vì CMP tràn", "Không dịch được vì 80h không vừa AL", "Y"], "a": 3, "e": "Có dấu: 127 so với −128. 7Fh − 80h = FFh, OF = 1 (127 + 128 = 255 tràn), SF = 1, SF = OF nên JL không nhảy (127 không nhỏ hơn −128); DL thành 'Y'. 80h vừa một byte."}, {"q": "Lệnh <code>JNE<\/code> nằm ở offset 0120h (2 byte), nhãn đích ở 0110h. Byte thứ hai của lệnh là gì?", "o": ["F0h", "10h", "EEh", "12h"], "a": 2, "e": "Độ dời = đích − địa chỉ lệnh kế tiếp = 0110h − 0122h = −12h = EEh (bù 2 của 12h). F0h là kết quả khi quên rằng gốc tính là lệnh kế tiếp."}, {"q": "Giữa <code>CMP AX, BX<\/code> và <code>JBE nho<\/code> cần chèn một lệnh. Lệnh nào <b>không<\/b> làm sai kết quả?", "o": ["<code>INC CX<\/code>", "<code>MOV CX, 5<\/code>", "<code>DEC DX<\/code>", "<code>ADD SI, 2<\/code>"], "a": 1, "e": "JBE đọc CF và ZF. MOV không đổi cờ. INC và DEC giữ CF nhưng đặt lại ZF theo CX, DX; ADD đặt lại cả CF và ZF."}]);

